s = '({[]})'
stack = []
pairs = {')': '(', ']': '[', '}': '{'}
ok = True
for ch in s:
    if ch in '([{':
        stack.append(ch)
    else:
        if stack and stack[-1] == pairs[ch]:
            stack.pop()
        else:
            ok = False
            break
print('匹配成功' if ok and not stack else '匹配失败')
